using BARANG.Core.Application.Abstractions.Actors;
using BARANG.Core.Application.Security;
using BARANG.Core.Domain.Security;
using BARANG.Core.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;
#pragma warning disable CA1725 // Overloaded persistence methods intentionally share the contract name.

namespace BARANG.Core.Infrastructure.Security;

public sealed class SecurityStore(CoreDbContext db) : ISecurityStore, IRemovalStore
{
    public void Add(ApplicationUser x) => db.ApplicationUsers.Add(x); public void Add(Role x) => db.Roles.Add(x); public void Add(RolePermission x) => db.RolePermissions.Add(x); public void Add(UserCompany x) => db.UserCompanies.Add(x); public void Add(UserRole x) => db.UserRoles.Add(x); public void Add(AuthenticationSession x) => db.AuthenticationSessions.Add(x); public void Add(SecurityAuditEvent x) => db.SecurityAuditEvents.Add(x); public void Remove(RolePermission x) => db.RolePermissions.Remove(x);
    public Task<ApplicationUser?> FindUserAsync(Guid id, CancellationToken ct) => db.ApplicationUsers.SingleOrDefaultAsync(x => x.Id == id, ct); public Task<ApplicationUser?> FindUserByUsernameAsync(string username, CancellationToken ct) => db.ApplicationUsers.SingleOrDefaultAsync(x => x.Username == username, ct); public async Task<IReadOnlyList<ApplicationUser>> ListUsersAsync(CancellationToken ct) => await db.ApplicationUsers.AsNoTracking().OrderBy(x => x.Username).ToListAsync(ct); public Task<bool> UsernameExistsAsync(string username, CancellationToken ct) => db.ApplicationUsers.AnyAsync(x => x.Username == username, ct);
    public Task<Role?> FindRoleAsync(Guid id, CancellationToken ct) => db.Roles.SingleOrDefaultAsync(x => x.Id == id, ct); public async Task<IReadOnlyList<Role>> ListRolesAsync(CancellationToken ct) => await db.Roles.AsNoTracking().OrderBy(x => x.Code).ToListAsync(ct); public Task<bool> RoleCodeExistsAsync(string code, CancellationToken ct) => db.Roles.AnyAsync(x => x.Code == code, ct);
    public Task<Permission?> FindPermissionAsync(Guid id, CancellationToken ct) => db.Permissions.SingleOrDefaultAsync(x => x.Id == id, ct); public async Task<IReadOnlyList<Permission>> ListPermissionsAsync(CancellationToken ct) => await db.Permissions.AsNoTracking().OrderBy(x => x.Code).ToListAsync(ct); public async Task<IReadOnlyList<Permission>> ListRolePermissionsAsync(Guid roleId, CancellationToken ct) => await (from rp in db.RolePermissions.AsNoTracking() join p in db.Permissions.AsNoTracking() on rp.PermissionId equals p.Id where rp.RoleId == roleId select p).ToListAsync(ct);
    public Task<UserCompany?> FindEffectiveCompanyAccessAsync(Guid userId, Guid companyId, DateTimeOffset now, CancellationToken ct) => db.UserCompanies.SingleOrDefaultAsync(x => x.UserId == userId && x.CompanyId == companyId && x.ValidFromUtc <= now && (x.ValidToUtc == null || x.ValidToUtc > now), ct); public async Task<IReadOnlyList<UserCompany>> ListCompanyAccessAsync(Guid userId, CancellationToken ct) => await db.UserCompanies.AsNoTracking().Where(x => x.UserId == userId).ToListAsync(ct); public Task<UserCompany?> FindOpenCompanyAccessAsync(Guid userId, Guid companyId, CancellationToken ct) => db.UserCompanies.SingleOrDefaultAsync(x => x.UserId == userId && x.CompanyId == companyId && x.ValidToUtc == null, ct);
    public Task<UserRole?> FindOpenUserRoleAsync(Guid userId, Guid roleId, Guid companyId, CancellationToken ct) => db.UserRoles.SingleOrDefaultAsync(x => x.UserId == userId && x.RoleId == roleId && x.CompanyId == companyId && x.ValidToUtc == null, ct); public async Task<IReadOnlyList<UserRole>> ListUserRolesAsync(Guid userId, CancellationToken ct) => await db.UserRoles.AsNoTracking().Where(x => x.UserId == userId).ToListAsync(ct);
    public Task<RolePermission?> FindRolePermissionAsync(Guid roleId, Guid permissionId, CancellationToken ct) => db.RolePermissions.SingleOrDefaultAsync(x => x.RoleId == roleId && x.PermissionId == permissionId, ct);
    public Task<bool> UserHasPermissionAsync(Guid userId, Guid companyId, string permission, DateTimeOffset now, CancellationToken ct) => (from u in db.ApplicationUsers where u.Id == userId && u.AccountState == UserAccountState.Active join uc in db.UserCompanies on u.Id equals uc.UserId join ur in db.UserRoles on new { u.Id, uc.CompanyId } equals new { Id = ur.UserId, ur.CompanyId } join r in db.Roles on ur.RoleId equals r.Id join rp in db.RolePermissions on r.Id equals rp.RoleId join p in db.Permissions on rp.PermissionId equals p.Id where uc.CompanyId == companyId && uc.ValidFromUtc <= now && (uc.ValidToUtc == null || uc.ValidToUtc > now) && ur.ValidFromUtc <= now && (ur.ValidToUtc == null || ur.ValidToUtc > now) && r.IsActive && p.Code == permission select p).AnyAsync(ct);
    public Task<AuthenticationSession?> FindSessionAsync(string tokenHash, DateTimeOffset now, CancellationToken ct) => db.AuthenticationSessions.SingleOrDefaultAsync(x => x.TokenHash == tokenHash && x.RevokedAtUtc == null && x.ExpiresAtUtc > now, ct); public async Task<IReadOnlyList<AuthenticationSession>> ListActiveSessionsAsync(Guid userId, DateTimeOffset now, CancellationToken ct) => await db.AuthenticationSessions.Where(x => x.UserId == userId && x.RevokedAtUtc == null && x.ExpiresAtUtc > now).ToListAsync(ct); public Task<bool> AnyUsersAsync(CancellationToken ct) => db.ApplicationUsers.AnyAsync(ct);
}

public sealed class RequestIdentityResolver(ISecurityStore store, ISessionTokenService tokens, TimeProvider time) : IRequestIdentityResolver
{
    public async Task<ActorContext?> ResolveAsync(string accessToken, CancellationToken ct) { AuthenticationSession? session = await store.FindSessionAsync(tokens.Hash(accessToken), time.GetUtcNow(), ct); if (session is null) return null; ApplicationUser? user = await store.FindUserAsync(session.UserId, ct); return user is { IsActive: true } ? new ActorContext(user.Id.ToString(), ActorType.InternalUser, true, SourceChannel.Backoffice, user.Id.ToString()) : null; }
}
#pragma warning restore CA1725
